try:
    val = int(input())
    print(val ** 2)
except ValueError:
    print("Không phải số nguyên")

def tinh_thuong(diem):
    if diem > 10 or diem < 0:
        raise ValueError("Điểm không hợp lệ")
    return diem

try:
    tinh_thuong(15)
except ValueError as e:
    print(e)
finally:
    print("Kết thúc")

class Person:
    def introduce(self):
        print("Tôi là con người.")
p = Person()
p.introduce()

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height
    def get_area(self):
        return self.width * self.height

rect = Rectangle(10, 20)
print(rect.get_area())

class Vehicle:
    def __init__(self, brand):
        self.brand = brand

class ElectricCar(Vehicle):
    def __init__(self, brand):
        super().__init__(brand)
    def show_brand(self):
        print(self.brand)

car = ElectricCar("Tesla")
car.show_brand()
